long mix_audio_cubic_soft(const int16_t *a, const int16_t *b,
                          float *out, int n, void *ctx)
{
    long clamped = 0;
    int i;
    (void)ctx;

    for (i = 0; i < n; i++) {
        double x = ((double)a[i] + (double)b[i]) / 32768.0;
        double v;

        if (x > 1.0) {
            v = 2.0 / 3.0;
            clamped++;
        } else if (x < -1.0) {
            v = -2.0 / 3.0;
            clamped++;
        } else {
            v = x - x * x * x / 3.0;
        }
        out[i] = (float)v;
    }
    return clamped;
}
