/*
 * test_cubic.c — mix_audio_cubic_soft 的临时单元验证（不入库）
 *
 * 独立 oracle：本文件自带一份参考实现，逐点对比 src/mix_algos.c 的被测函数。
 * 覆盖：零点、±1 接点（边界不计数）、平台段、原点斜率、奇对称、
 *       全域单调非降、|y|<=2/3、钳位计数、与 int16 域线性叠加参考的一致性。
 */
#include <stdio.h>
#include <math.h>
#include "mix_algos.h"

static int fails = 0;

static void chk(const char *what, double got, double want, double tol)
{
    if (fabs(got - want) > tol) {
        printf("FAIL %-38s got %.9f want %.9f\n", what, got, want);
        fails++;
    } else {
        printf("ok   %-38s %.9f\n", what, got);
    }
}

/* 独立参考实现（oracle），按 JOS PASP 三分段公式逐字写 */
static double ref_cubic(double x)
{
    if (x > 1.0)  return 2.0 / 3.0;
    if (x < -1.0) return -2.0 / 3.0;
    return x - (x * x * x) / 3.0;
}

int main(void)
{
    int16_t a[4], b[4];
    float out[4];
    long c;

    /* 1) 零点：y(0)=0，原点斜率 1（小信号近似线性） */
    a[0] = 0; b[0] = 0;
    c = mix_audio_cubic_soft(a, b, out, 1, NULL);
    chk("y(0) == 0", out[0], 0.0, 1e-9);
    chk("y(0) 不钳位", (double)c, 0.0, 0.0);

    a[0] = 8192; b[0] = 0;             /* x = 0.25 */
    mix_audio_cubic_soft(a, b, out, 1, NULL);
    chk("y(0.25) == 0.25-0.25^3/3", out[0], ref_cubic(0.25), 1e-7);

    /* 2) ±1 接点：x 恰为 ±1 属于中段，值 = ±2/3，且不计数 */
    a[0] = 16384; b[0] = 16384;        /* x = 1.0 精确 */
    c = mix_audio_cubic_soft(a, b, out, 1, NULL);
    chk("y(+1) == 2/3（接点值连续）", out[0], 2.0 / 3.0, 1e-7);
    chk("x=+1 不计钳位", (double)c, 0.0, 0.0);

    a[0] = -16384; b[0] = -16384;      /* x = -1.0 精确 */
    c = mix_audio_cubic_soft(a, b, out, 1, NULL);
    chk("y(-1) == -2/3（接点值连续）", out[0], -2.0 / 3.0, 1e-7);
    chk("x=-1 不计钳位", (double)c, 0.0, 0.0);

    /* 3) 平台段：|x|>1 钳到 ±2/3 并计数 */
    a[0] = 16385; b[0] = 16384;        /* x = 32769/32768 > 1 */
    c = mix_audio_cubic_soft(a, b, out, 1, NULL);
    chk("y(>1) == +2/3", out[0], 2.0 / 3.0, 1e-7);

    a[0] = 32767; b[0] = 32767;        /* x ≈ +2.0 */
    c = mix_audio_cubic_soft(a, b, out, 1, NULL);
    chk("y(+2) == +2/3", out[0], 2.0 / 3.0, 1e-7);
    chk("y(+2) 计 1 个钳位", (double)c, 1.0, 0.0);

    a[0] = -32768; b[0] = -32768;      /* x = -2.0 */
    c = mix_audio_cubic_soft(a, b, out, 1, NULL);
    chk("y(-2) == -2/3", out[0], -2.0 / 3.0, 1e-7);
    chk("y(-2) 计 1 个钳位", (double)c, 1.0, 0.0);

    /* 4) 奇对称：f(-x) = -f(x) */
    a[0] = 12000; b[0] = 3456;
    a[1] = -12000; b[1] = -3456;
    mix_audio_cubic_soft(a, b, out, 2, NULL);
    chk("奇对称 f(-x) == -f(x)", out[1], -out[0], 1e-9);

    /* 5) 全域扫描 a=b=k：x∈[-2,2)，单调非降、有界、逐点等于 oracle、计数一致 */
    {
        enum { N = 65536 };
        static int16_t sa[N], sb[N];
        static float so[N];
        long want_c = 0;
        double prev = -1e9;
        int i, bad = 0;
        for (i = 0; i < N; i++) {
            int k = i - 32768;
            sa[i] = (int16_t)k; sb[i] = (int16_t)k;
        }
        c = mix_audio_cubic_soft(sa, sb, so, N, NULL);
        for (i = 0; i < N; i++) {
            double x = 2.0 * (i - 32768) / 32768.0;
            double want = ref_cubic(x);
            if (x > 1.0 || x < -1.0) want_c++;
            if (fabs(so[i] - want) > 1e-6 || so[i] < prev - 1e-9
                || fabs(so[i]) > 2.0 / 3.0 + 1e-9)
                bad++;
            prev = so[i];
        }
        chk("全域 65536 点逐点匹配 oracle、单调、有界", (double)bad, 0.0, 0.0);
        chk("全域钳位计数 == |x|>1 样本数", (double)c, (double)want_c, 0.0);
    }

    /* 6) 无状态：同输入重复调用结果一致 */
    a[0] = 20000; b[0] = -9000;
    mix_audio_cubic_soft(a, b, out, 1, NULL);
    {
        float first = out[0];
        mix_audio_cubic_soft(a, b, out, 1, NULL);
        chk("无状态：重复调用结果一致", out[0], first, 0.0);
    }

    printf(fails ? "\n== %d 项失败 ==\n" : "\n== 全部通过 ==\n", fails);
    return fails ? 1 : 0;
}

